using System;using System.IO;using System.IO.Ports;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Linq;using System.Diagnostics;using System.Threading;using Microsoft.Win32;
namespace JonsboStudio {
 sealed class DeviceInfo {public string port,name,hardwareId,serial="";public int width=1920,height=462,problemCode;public bool ready=true;}
 interface IDisplayTransport:IDisposable {string SerialNumber{get;}int NativeWidth{get;}int NativeHeight{get;}void Connect(string port);void Send(byte[] jpeg);}
 sealed class JonsboTransport:IDisplayTransport {
  SerialPort serial;string serialNumber="";int nativeWidth,nativeHeight;public string SerialNumber{get{return serialNumber;}}public int NativeWidth{get{return nativeWidth;}}public int NativeHeight{get{return nativeHeight;}}
  public static List<DeviceInfo> Discover(){var list=new List<DeviceInfo>();var present=SerialPort.GetPortNames();using(var usb=Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Enum\USB")){if(usb!=null)foreach(string hardware in usb.GetSubKeyNames()){if(!Regex.IsMatch(hardware,@"^VID_33C3&PID_(7788|F101|0E02|F102)(?:&|$)",RegexOptions.IgnoreCase))continue;try{using(var device=usb.OpenSubKey(hardware)){if(device==null)continue;foreach(string instance in device.GetSubKeyNames())using(var info=device.OpenSubKey(instance)){if(info==null)continue;using(var parameters=info.OpenSubKey("Device Parameters")){string port=parameters==null?null:parameters.GetValue("PortName") as string;if(!string.IsNullOrEmpty(port)&&Array.Exists(present,x=>string.Equals(x,port,StringComparison.OrdinalIgnoreCase))&&!list.Exists(x=>x.port==port))list.Add(new DeviceInfo{port=port,name=hardware.StartsWith("VID_33C3&PID_F101&MI_00",StringComparison.OrdinalIgnoreCase)?"JONSBO DS916":"JONSBO display",hardwareId=hardware+"\\"+instance});}}}}catch(IOException){}catch(UnauthorizedAccessException){}}}try{list.AddRange(UsbDiscovery.Displays(list));}catch(Exception error){FirstRunSetup.Log(error,"USB display discovery");}return list.OrderBy(x=>x.port==MsDisplayTransport.PortId?1000:int.Parse(Regex.Match(x.port,@"\d+").Value)).ToList();}
  public void Connect(string port){
   if(Process.GetProcessesByName("JONSBO-AIO").Length>0)throw new InvalidOperationException("Exit the official JONSBO display app from its tray before connecting. The display COM port has one owner.");
   var devices=Discover();var selected=devices.FirstOrDefault(x=>x.port==port);if(selected!=null&&!selected.ready)throw new IOException(selected.problemCode==14?"Windows requires a restart for the DS916 USB interface.":"DS916 USB interface is not ready. Reconnect its USB cable and refresh devices.");if(selected==null)throw new InvalidOperationException("Selected port is not a supported JONSBO display.");
   serial=new SerialPort(port,9600,Parity.None,8,StopBits.One){Handshake=Handshake.None,DtrEnable=true,ReadTimeout=250,WriteTimeout=1500,ReadBufferSize=65536,WriteBufferSize=65536};
   try{if(DeviceConnection.Trace)Console.WriteLine("DS916: opening serial "+port);serial.Open();if(DeviceConnection.Trace)Console.WriteLine("DS916: reading handshake");serial.DiscardInBuffer();serial.Write(new byte[]{0xF0,0xA5,0x5A,0x0F},0,4);var answer=new StringBuilder();var timer=Stopwatch.StartNew();while(timer.ElapsedMilliseconds<1800){try{answer.Append(serial.ReadExisting());}catch(TimeoutException){}var match=Regex.Match(answer.ToString(),@"(VMAX[A-Z].*?(\d{4}))\*(\d{3,4})[SC]\d+");if(match.Success){serialNumber=match.Value;nativeWidth=int.Parse(match.Groups[2].Value);nativeHeight=int.Parse(match.Groups[3].Value);break;}Thread.Sleep(20);}if(NativeWidth<100||NativeHeight<100)throw new IOException("The JONSBO display did not return a valid size and serial number. Close other display apps and reconnect USB.");}
   catch{Dispose();throw;}
  }
  public void Send(byte[] jpeg){if(jpeg==null||jpeg.Length<4||jpeg[0]!=255||jpeg[1]!=216||jpeg[jpeg.Length-2]!=255||jpeg[jpeg.Length-1]!=217)throw new InvalidDataException("Invalid JPEG frame.");serial.BaseStream.Write(jpeg,0,jpeg.Length);}
  public void Dispose(){if(serial!=null){try{serial.Close();}finally{serial.Dispose();serial=null;}}}
 }
}
